const PACKS: Partial<Record<GameLocale, Pack>> = { en: EN, de: DE, nl: NL, es: ES, it: IT, pt: PT, pl: PL }

function publicSafeDocument(document: LegalDocument): LegalDocument {
  const copy: LegalDocument = {
    ...document,
    sections: document.sections.map(section => ({
      ...section,
      paragraphs: [...section.paragraphs],
      bullets: section.bullets ? [...section.bullets] : undefined,
    })),
  }

  // Version temporaire sans identité personnelle publiée dans le jeu.
  // Les informations d'éditeur/contact privées ne sont ni affichées ni nécessaires
  // tant que la distribution reste gratuite et sans compte/paiement.
  if (copy.id === 'LEGAL') {
    copy.sections = copy.sections.filter((_, index) => index !== 0 && index !== 3)
  }

  if (copy.id === 'PRIVACY') {
    copy.sections = copy.sections.filter((_, index) => index !== 0)
    const rights = copy.sections.find(section => /^11[.\s]/.test(section.title) || /rights|rechten|rechte|derechos|diritti|direitos|prawa/i.test(section.title))
    if (rights && rights.paragraphs.length > 1) rights.paragraphs.splice(1, 1)
  }

  if (copy.id === 'CGV') {
    if (copy.sections[1]?.paragraphs.length) copy.sections[1].paragraphs = copy.sections[1].paragraphs.slice(1)
    if (copy.sections[8]?.paragraphs.length > 1) copy.sections[8].paragraphs = copy.sections[8].paragraphs.slice(0, 1)
    if (copy.sections[12]) copy.sections = copy.sections.filter((_, index) => index !== 12)
  }

  const privateValues = [
    seller.sellerName,
    seller.address,
    seller.email,
    seller.phone,
    seller.registration,
    seller.vat,
    seller.mediatorName,
    seller.mediatorAddress,
    seller.mediatorUrl,
  ].filter((value): value is string => Boolean(value && value.trim()))

  if (privateValues.length) {
    copy.sections = copy.sections
      .map(section => ({
        ...section,
        paragraphs: section.paragraphs.filter(paragraph => !privateValues.some(value => paragraph.includes(value))),
        bullets: section.bullets?.filter(item => !privateValues.some(value => item.includes(value))),
      }))
      .filter(section => section.paragraphs.length > 0 || (section.bullets?.length ?? 0) > 0)
  }

  return copy
}

export function localizedLegalDocument(id: LegalDocumentId, locale: GameLocale): LegalDocument {
  const source = locale === 'fr' ? LEGAL_DOCUMENTS[id] : (PACKS[locale]?.[id] ?? EN[id])
  return publicSafeDocument(source)
}
